WITH web_events_by_session AS (SELECT session_id, AVG(duration_sec) AS avg_duration_sec FROM web_events WHERE event_time >= '2025-01-15' GROUP BY session_id) SELECT sessions.id, sessions.started_at, sessions.country, web_events_by_session.avg_duration_sec FROM sessions LEFT JOIN web_events_by_session ON sessions.id = web_events_by_session.session_id WHERE web_events_by_session.avg_duration_sec >= 240;
